package ai.generated;

import ai.abstraction.AbstractionLayerAI;
import ai.abstraction.AbstractAction;
import ai.abstraction.pathfinding.AStarPathFinding;
import ai.abstraction.pathfinding.PathFinding;
import ai.core.AI;
import ai.core.ParameterSpecification;
import java.util.ArrayList;
import java.util.List;
import rts.GameState;
import rts.PhysicalGameState;
import rts.PlayerAction;
import rts.ResourceUsage;
import rts.UnitAction;
import rts.units.Unit;
import rts.units.UnitType;
import rts.units.UnitTypeTable;

public final class CandidateAgent extends AbstractionLayerAI {
    private UnitTypeTable utt;
    private UnitType resourceType;
    private UnitType workerType;
    private UnitType lightType;
    private UnitType heavyType;
    private UnitType rangedType;
    private UnitType baseType;
    private UnitType barracksType;
    private int activePlayer = -1;
    private GameState activeGameState;

    public CandidateAgent(UnitTypeTable utt) {
        this(utt, new AStarPathFinding());
    }

    public CandidateAgent(UnitTypeTable utt, AStarPathFinding pathFinding) {
        super(pathFinding);
        reset(utt);
    }

    public void reset(UnitTypeTable utt) {
        this.utt = utt;
        activePlayer = -1;
        activeGameState = null;
        resourceType = utt.getUnitType("Resource");
        workerType = utt.getUnitType("Worker");
        lightType = utt.getUnitType("Light");
        heavyType = utt.getUnitType("Heavy");
        rangedType = utt.getUnitType("Ranged");
        baseType = utt.getUnitType("Base");
        barracksType = utt.getUnitType("Barracks");
    }

    @Override
    public void reset() {
        super.reset();
        if (utt != null) {
            reset(utt);
        }
    }

    @Override
    public AI clone() {
        return new CandidateAgent(utt, new AStarPathFinding());
    }

    @Override
    public PlayerAction getAction(int player, GameState gs) throws Exception {
        activePlayer = player;
        activeGameState = gs;
        try {
            if (gs.gameover()) {
                return translateActions(player, gs);
            }
            AgentContext context = new AgentContext(player, gs, new ArrayList<>(gs.getUnits()));
            decide(context);
            applyAutoDefense(player, gs);
            return translateActions(player, gs);
        } finally {
            activePlayer = -1;
            activeGameState = null;
        }
    }

    // EAGLE_AGENT_STRATEGY_START
    // Deterministic finite-control framework: economy, construction, production,
    // rallying, target selection, and defense are independently recombinable.
    private static final int WORKER_TARGET = {{EAGLE_SLOT:worker_target}};
    private static final int BARRACKS_WORKER_THRESHOLD = {{EAGLE_SLOT:barracks_worker_threshold}};
    private static final int BARRACKS_TARGET = {{EAGLE_SLOT:barracks_target}};
    private static final boolean BUILD_BARRACKS = {{EAGLE_SLOT:build_barracks}};
    private static final int BUILD_DIRECTION = {{EAGLE_SLOT:build_direction}};
    private static final int BUILD_RETRY = {{EAGLE_SLOT:build_retry}};
    private static final int RESOURCE_POLICY = {{EAGLE_SLOT:resource_policy}};
    private static final int MINIMUM_RESOURCE_DISTANCE = {{EAGLE_SLOT:minimum_resource_distance}};
    private static final int WORKER_ASSIGNMENT = {{EAGLE_SLOT:worker_assignment}};
    private static final int WORKER_FALLBACK = {{EAGLE_SLOT:worker_fallback}};
    private static final int PRODUCTION_PRIORITY = {{EAGLE_SLOT:production_priority}};
    private static final int EXPANSION_MODE = {{EAGLE_SLOT:expansion_mode}};
    private static final int COMBAT_UNIT_KIND = {{EAGLE_SLOT:combat_unit_kind}};
    private static final int ARMY_TARGET = {{EAGLE_SLOT:army_target}};
    private static final int WORKER_RESERVE = {{EAGLE_SLOT:worker_reserve}};
    private static final int COMBAT_TARGET_LIMIT = {{EAGLE_SLOT:combat_target_limit}};
    private static final int ATTACK_COMMIT_COUNT = {{EAGLE_SLOT:attack_commit_count}};
    private static final int ATTACK_TRIGGER = {{EAGLE_SLOT:attack_trigger}};
    private static final int TARGET_PRIORITY = {{EAGLE_SLOT:target_priority}};
    private static final boolean FOCUS_FIRE = {{EAGLE_SLOT:focus_fire}};
    private static final int ATTACK_ORDER = {{EAGLE_SLOT:attack_order}};
    private static final int TARGET_DISTANCE_WEIGHT = {{EAGLE_SLOT:target_distance_weight}};
    private static final int ATTACK_DISTANCE_POLICY = {{EAGLE_SLOT:attack_distance_policy}};
    private static final int ATTACK_RANGE_MARGIN = {{EAGLE_SLOT:attack_range_margin}};
    private static final int RALLY_POLICY = {{EAGLE_SLOT:rally_policy}};
    private static final int COMBAT_FALLBACK = {{EAGLE_SLOT:combat_fallback}};
    private static final boolean AUTO_DEFENSE = {{EAGLE_SLOT:auto_defense}};

    private void decide(AgentContext context) {
        if (PRODUCTION_PRIORITY == 0) {
            ensureBarracks(context);
            trainWorker(context);
            trainCombat(context);
        } else if (PRODUCTION_PRIORITY == 1) {
            trainCombat(context);
            ensureBarracks(context);
            trainWorker(context);
        } else {
            economy(context);
            ensureBarracks(context);
            trainWorker(context);
            trainCombat(context);
        }
        economy(context);
        combat(context);
    }

    private void economy(AgentContext context) {
        Unit base = ownBase(context);
        for (Unit unit : context.units) {
            if (!isIdleAlly(unit, context) || unit.getType() != workerType) {
                continue;
            }
            if (shouldReserveWorker(unit, context)) {
                commandIdle(unit);
                continue;
            }
            Unit resource = selectResource(context, unit, base);
            if (resource != null && base != null) {
                commandHarvest(unit, resource, base);
            } else if (WORKER_FALLBACK == 1 && unit.getResources() > 0 && base != null) {
                commandReturn(unit, base, context);
            } else if (WORKER_FALLBACK == 2 && base != null) {
                commandMove(unit, base.getX(), base.getY());
            } else {
                commandIdle(unit);
            }
        }
    }

    private boolean shouldReserveWorker(Unit worker, AgentContext context) {
        if (WORKER_ASSIGNMENT == 0 || !BUILD_BARRACKS
                || countOwnUnits(context, barracksType) >= BARRACKS_TARGET
                || countOwnUnits(context, workerType) < BARRACKS_WORKER_THRESHOLD) {
            return false;
        }
        int reserved = 0;
        for (Unit candidate : context.units) {
            if (candidate.getPlayer() == context.player && candidate.getType() == workerType
                    && isIdleAlly(candidate, context)) {
                if (candidate == worker) {
                    return reserved < WORKER_ASSIGNMENT;
                }
                reserved++;
            }
        }
        return false;
    }

    private boolean ensureBarracks(AgentContext context) {
        if (!BUILD_BARRACKS
                || countOwnUnits(context, barracksType) >= BARRACKS_TARGET
                || countOwnUnits(context, workerType) < BARRACKS_WORKER_THRESHOLD
                || context.gs.getPlayer(context.player).getResources() < barracksType.cost) {
            return false;
        }
        Unit base = ownBase(context);
        if (base == null) {
            return false;
        }
        for (Unit worker : context.units) {
            if (!isIdleAlly(worker, context) || worker.getType() != workerType) {
                continue;
            }
            int[][] offsets = {{0, -1}, {1, 0}, {0, 1}, {-1, 0}};
            for (int attempt = 0; attempt < BUILD_RETRY; attempt++) {
                int direction = (BUILD_DIRECTION + attempt) % offsets.length;
                int x = base.getX() + offsets[direction][0];
                int y = base.getY() + offsets[direction][1];
                if (isFreeCell(context, x, y) && commandBuild(worker, barracksType, x, y)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean trainWorker(AgentContext context) {
        int workers = countOwnUnits(context, workerType);
        if (workers >= workerLimit(context)) {
            return false;
        }
        for (Unit unit : context.units) {
            if (isIdleAlly(unit, context) && unit.getType() == baseType
                    && context.gs.getPlayer(context.player).getResources() >= workerType.cost) {
                return commandTrain(unit, workerType);
            }
        }
        return false;
    }

    private boolean trainCombat(AgentContext context) {
        UnitType combatType = combatType();
        if (countOwnUnits(context, workerType) < WORKER_RESERVE
                || countOwnUnits(context, combatType) >= ARMY_TARGET) {
            return false;
        }
        for (Unit unit : context.units) {
            if (isIdleAlly(unit, context) && unit.getType() == barracksType
                    && context.gs.getPlayer(context.player).getResources() >= combatType.cost) {
                return commandTrain(unit, combatType);
            }
        }
        return false;
    }

    private int countOwnUnits(AgentContext context, UnitType type) {
        int count = 0;
        for (Unit unit : context.units) {
            if (unit.getPlayer() == context.player && unit.getType() == type) {
                count++;
            }
        }
        return count;
    }

    private int workerLimit(AgentContext context) {
        if (EXPANSION_MODE == 0) {
            return WORKER_TARGET;
        }
        if (EXPANSION_MODE == 1 && countOwnUnits(context, barracksType) == 0) {
            return Math.min(WORKER_TARGET, BARRACKS_WORKER_THRESHOLD + 1);
        }
        return Math.min(WORKER_TARGET, BARRACKS_WORKER_THRESHOLD);
    }

    private void combat(AgentContext context) {
        if (!attackReady(context)) {
            rally(context);
            return;
        }
        Unit focusTarget = null;
        int assigned = 0;
        int passes = ATTACK_ORDER == 2 ? 2 : 1;
        for (int pass = 0; pass < passes && assigned < COMBAT_TARGET_LIMIT; pass++) {
            for (int offset = 0; offset < context.units.size()
                    && assigned < COMBAT_TARGET_LIMIT; offset++) {
                int index = ATTACK_ORDER == 1
                        ? context.units.size() - 1 - offset : offset;
                Unit unit = context.units.get(index);
                if (!isIdleAlly(unit, context) || !unit.getType().canAttack) {
                    continue;
                }
                boolean selectedType = unit.getType() == combatType();
                if (ATTACK_ORDER == 2 && ((pass == 0) != selectedType)) {
                    continue;
                }
                Unit target = FOCUS_FIRE && focusTarget != null
                        ? focusTarget : selectTarget(context, unit, context.units);
                if (target == null) {
                    combatFallback(unit, null);
                    continue;
                }
                if (FOCUS_FIRE && focusTarget == null) {
                    focusTarget = target;
                }
                int distance = Math.abs(target.getX() - unit.getX())
                        + Math.abs(target.getY() - unit.getY());
                if (ATTACK_DISTANCE_POLICY == 1
                        && distance > unit.getType().attackRange + ATTACK_RANGE_MARGIN) {
                    combatFallback(unit, target);
                    continue;
                }
                if (commandAttack(unit, target)) {
                    assigned++;
                } else {
                    combatFallback(unit, target);
                }
            }
        }
    }

    private boolean attackReady(AgentContext context) {
        int combatCount = countOwnUnits(context, combatType());
        if (ATTACK_TRIGGER == 0) {
            return true;
        }
        if (ATTACK_TRIGGER == 1) {
            return combatCount >= ATTACK_COMMIT_COUNT;
        }
        return combatCount >= Math.max(ATTACK_COMMIT_COUNT, ARMY_TARGET);
    }

    private void rally(AgentContext context) {
        Unit base = ownBase(context);
        Unit target = base == null ? null : nearestEnemy(base, context);
        for (Unit unit : context.units) {
            if (!isIdleAlly(unit, context) || !unit.getType().canAttack) {
                continue;
            }
            if (RALLY_POLICY == 1 && target != null) {
                commandMove(unit, target.getX(), target.getY());
            } else if (RALLY_POLICY == 2 && target != null) {
                commandAttack(unit, target);
            } else {
                commandIdle(unit);
            }
        }
    }

    private void combatFallback(Unit unit, Unit target) {
        if (COMBAT_FALLBACK == 1 && target != null) {
            commandMove(unit, target.getX(), target.getY());
        } else {
            commandIdle(unit);
        }
    }

    private Unit selectResource(AgentContext context, Unit source, Unit base) {
        Unit best = null;
        int bestScore = Integer.MAX_VALUE;
        for (Unit candidate : context.units) {
            if (candidate.getPlayer() >= 0 || candidate.getType() != resourceType) {
                continue;
            }
            int workerDistance = Math.abs(candidate.getX() - source.getX())
                    + Math.abs(candidate.getY() - source.getY());
            if (workerDistance < MINIMUM_RESOURCE_DISTANCE) {
                continue;
            }
            int baseDistance = base == null ? workerDistance
                    : Math.abs(candidate.getX() - base.getX())
                    + Math.abs(candidate.getY() - base.getY());
            int score = RESOURCE_POLICY == 0 ? workerDistance
                    : RESOURCE_POLICY == 1 ? baseDistance : workerDistance + baseDistance;
            if (score < bestScore
                    || (score == bestScore && (best == null || candidate.getID() < best.getID()))) {
                best = candidate;
                bestScore = score;
            }
        }
        return best;
    }

    private UnitType combatType() {
        if (COMBAT_UNIT_KIND == 1) {
            return heavyType;
        }
        if (COMBAT_UNIT_KIND == 2) {
            return rangedType;
        }
        return lightType;
    }

    private Unit selectTarget(AgentContext context, Unit actor, List<Unit> candidates) {
        Unit best = null;
        int bestScore = Integer.MAX_VALUE;
        for (Unit candidate : candidates) {
            if (candidate.getPlayer() < 0 || candidate.getPlayer() == context.player) {
                continue;
            }
            int distance = actor == null ? 0 : Math.abs(candidate.getX() - actor.getX())
                    + Math.abs(candidate.getY() - actor.getY());
            int rank = targetRank(candidate);
            int score = rank * 100000 + distance * TARGET_DISTANCE_WEIGHT;
            if (score < bestScore
                    || (score == bestScore && (best == null || candidate.getID() < best.getID()))) {
                best = candidate;
                bestScore = score;
            }
        }
        return best;
    }

    private int targetRank(Unit candidate) {
        if (TARGET_PRIORITY == 1) {
            return candidate.getType() == baseType ? 0 : 1;
        }
        if (TARGET_PRIORITY == 2) {
            return candidate.getType() == barracksType ? 0 : 1;
        }
        if (TARGET_PRIORITY == 3) {
            return candidate.getType() == workerType ? 0 : 1;
        }
        if (TARGET_PRIORITY == 4) {
            return candidate.getType().canAttack ? 0 : 1;
        }
        return 0;
    }

    private PathChoice findPath(AgentContext context, Unit unit, int targetX, int targetY) {
        return new PathChoice(targetX, targetY);
    }

    // EAGLE_AGENT_STRATEGY_END

    // EAGLE_ACTION_HELPERS_START
    // Stable Agent operation API: strategy code should issue actions through these helpers.
    private boolean commandMove(Unit unit, int x, int y) {
        if (unit == null || unit.getPlayer() != activePlayer
                || unit.getType() == baseType || unit.getType() == barracksType
                || !isInsideActiveMap(x, y)) {
            return false;
        }
        move(unit, x, y);
        return true;
    }

    private boolean commandHarvest(Unit worker, Unit resource, Unit base) {
        if (worker == null || resource == null || base == null) {
            return false;
        }
        if (worker.getPlayer() != activePlayer || base.getPlayer() != activePlayer
                || resource.getPlayer() >= 0 || worker.getType() != workerType
                || resource.getType() != resourceType || base.getType() != baseType) {
            return false;
        }
        harvest(worker, resource, base);
        return true;
    }

    private boolean commandReturn(Unit worker, Unit base, AgentContext context) {
        UnitAction planned = prepareReturn(worker, base, context);
        return planned != null && commandReturn(worker, base, context, planned);
    }

    private boolean commandReturn(Unit worker, Unit base, AgentContext context, UnitAction planned) {
        UnitAction expected = prepareReturn(worker, base, context);
        if (expected == null || !expected.equals(planned)
                || !commandPlannedAction(worker, planned, context)) {
            return false;
        }
        actions.put(worker, new ReturnAction(worker, base, planned));
        return true;
    }

    private UnitAction prepareReturn(Unit worker, Unit base, AgentContext context) {
        if (context == null || context.gs != activeGameState || context.player != activePlayer
                || !isIdleAlly(worker, context) || base == null
                || worker.getType() != workerType || base.getType() != baseType
                || base.getPlayer() != context.player || worker.getResources() <= 0
                || !context.units.contains(base)) {
            return null;
        }
        int dx = base.getX() - worker.getX();
        int dy = base.getY() - worker.getY();
        UnitAction action;
        if (Math.abs(dx) + Math.abs(dy) == 1) {
            int direction = dx == 1 ? UnitAction.DIRECTION_RIGHT
                    : dx == -1 ? UnitAction.DIRECTION_LEFT
                    : dy == 1 ? UnitAction.DIRECTION_DOWN : UnitAction.DIRECTION_UP;
            action = new UnitAction(UnitAction.TYPE_RETURN, direction);
        } else {
            action = pf.findPathToAdjacentPosition(worker,
                    base.getX() + base.getY() * context.gs.getPhysicalGameState().getWidth(),
                    context.gs, context.reservations);
        }
        return action != null && context.gs.isUnitActionAllowed(worker, action)
                && context.reservations.consistentWith(
                        action.resourceUsage(worker, context.gs.getPhysicalGameState()), context.gs)
                ? action : null;
    }

    private boolean commandPlannedAction(Unit actor, UnitAction action, AgentContext context) {
        if (context == null || context.gs != activeGameState || context.player != activePlayer
                || action == null || !isIdleAlly(actor, context) || !context.units.contains(actor)
                || !actor.canExecuteAction(action, context.gs)
                || !context.gs.isUnitActionAllowed(actor, action)) {
            return false;
        }
        ResourceUsage usage = action.resourceUsage(actor, context.gs.getPhysicalGameState());
        if (!context.reservations.consistentWith(usage, context.gs)) {
            return false;
        }
        actions.put(actor, new PlannedUnitAction(actor, action));
        context.reservations.merge(usage);
        return true;
    }

    private boolean commandTrain(Unit producer, UnitType unitType) {
        if (producer == null || producer.getPlayer() != activePlayer || unitType == null) {
            return false;
        }
        boolean validBaseProduction = producer.getType() == baseType && unitType == workerType;
        boolean validBarracksProduction = producer.getType() == barracksType
                && (unitType == lightType || unitType == heavyType || unitType == rangedType);
        if (!validBaseProduction && !validBarracksProduction) {
            return false;
        }
        train(producer, unitType);
        return true;
    }

    private boolean commandBuild(Unit worker, UnitType buildingType, int x, int y) {
        if (worker == null || worker.getPlayer() != activePlayer || buildingType == null
                || worker.getType() != workerType
                || (buildingType != baseType && buildingType != barracksType)
                || !isInsideActiveMap(x, y)) {
            return false;
        }
        build(worker, buildingType, x, y);
        return true;
    }

    private boolean commandAttack(Unit attacker, Unit target) {
        if (attacker == null || target == null || attacker.getPlayer() != activePlayer
                || target.getPlayer() < 0 || !attacker.getType().canAttack) {
            return false;
        }
        if (target.getPlayer() == activePlayer) {
            return false;
        }
        attack(attacker, target);
        return true;
    }

    private boolean commandIdle(Unit unit) {
        if (unit == null || unit.getPlayer() != activePlayer) {
            return false;
        }
        idle(unit);
        return true;
    }

    private boolean isInsideActiveMap(int x, int y) {
        if (activeGameState == null) {
            return false;
        }
        PhysicalGameState physical = activeGameState.getPhysicalGameState();
        return x >= 0 && y >= 0 && x < physical.getWidth() && y < physical.getHeight();
    }

    // EAGLE_ACTION_HELPERS_END

    private boolean isIdleAlly(Unit unit, AgentContext context) {
        return unit != null
                && unit.getPlayer() == context.player
                && context.gs.getUnitAction(unit) == null
                && getAbstractAction(unit) == null;
    }

    private Unit nearestUnit(Unit source, List<Unit> units, int owner, UnitType type) {
        Unit best = null;
        int bestDistance = Integer.MAX_VALUE;
        for (Unit other : units) {
            if (owner != Integer.MIN_VALUE && other.getPlayer() != owner) {
                continue;
            }
            if (type != null && other.getType() != type) {
                continue;
            }
            int distance = Math.abs(other.getX() - source.getX()) + Math.abs(other.getY() - source.getY());
            if (distance < bestDistance) {
                best = other;
                bestDistance = distance;
            }
        }
        return best;
    }

    private Unit nearestEnemy(Unit source, AgentContext context) {
        Unit best = null;
        int bestDistance = Integer.MAX_VALUE;
        for (Unit other : context.units) {
            if (other.getPlayer() < 0 || other.getPlayer() == context.player) {
                continue;
            }
            int distance = Math.abs(other.getX() - source.getX()) + Math.abs(other.getY() - source.getY());
            if (distance < bestDistance) {
                best = other;
                bestDistance = distance;
            }
        }
        return best;
    }

    private Unit nearestResource(Unit source, AgentContext context) {
        return nearestUnit(source, context.units, -1, resourceType);
    }

    private Unit ownBase(AgentContext context) {
        for (Unit unit : context.units) {
            if (unit.getPlayer() == context.player && unit.getType() == baseType) {
                return unit;
            }
        }
        return null;
    }

    private boolean isFreeCell(AgentContext context, int x, int y) {
        if (context == null || context.gs == null) {
            return false;
        }
        PhysicalGameState physical = context.gs.getPhysicalGameState();
        return x >= 0 && y >= 0 && x < physical.getWidth() && y < physical.getHeight()
                && context.gs.free(x, y);
    }

    private void applyAutoDefense(int player, GameState gs) {
        PhysicalGameState pgs = gs.getPhysicalGameState();
        AgentContext context = new AgentContext(player, gs, new ArrayList<>(pgs.getUnits()));
        for (Unit ally : context.units) {
            if (!AUTO_DEFENSE || !isIdleAlly(ally, context) || !ally.getType().canAttack) {
                continue;
            }
            Unit enemy = nearestEnemy(ally, context);
            if (enemy == null) {
                continue;
            }
            int distance = Math.abs(enemy.getX() - ally.getX()) + Math.abs(enemy.getY() - ally.getY());
            if (distance <= ally.getType().attackRange) {
                commandAttack(ally, enemy);
            }
        }
    }

    @Override
    public List<ParameterSpecification> getParameters() {
        List<ParameterSpecification> parameters = new ArrayList<>();
        parameters.add(new ParameterSpecification("PathFinding", PathFinding.class, new AStarPathFinding()));
        return parameters;
    }

    private static final class AgentContext {
        final int player;
        final GameState gs;
        final List<Unit> units;
        final ResourceUsage reservations;

        AgentContext(int player, GameState gs, List<Unit> units) {
            this.player = player;
            this.gs = gs;
            this.units = units;
            this.reservations = gs.getResourceUsage().clone();
        }
    }

    // One-cycle primitives retain the compiler's exact placement and reservations.
    private static class PlannedUnitAction extends AbstractAction {
        private final UnitAction action;
        private boolean executed;

        PlannedUnitAction(Unit actor, UnitAction action) {
            super(actor);
            this.action = action;
        }

        @Override
        public boolean completed(GameState gs) {
            return executed;
        }

        @Override
        public UnitAction execute(GameState gs, ResourceUsage usage) {
            executed = true;
            return action;
        }

        @Override
        public void toxml(util.XMLWriter writer) {
            writer.tagWithAttributes("PlannedUnitAction", "unitID=\"" + getUnit().getID() + "\"");
            writer.tag("/PlannedUnitAction");
        }
    }

    private static final class ReturnAction extends PlannedUnitAction {
        private final Unit base;

        ReturnAction(Unit worker, Unit base, UnitAction action) {
            super(worker, action);
            this.base = base;
        }

        @Override
        public void toxml(util.XMLWriter writer) {
            writer.tagWithAttributes("Return", "unitID=\"" + getUnit().getID()
                    + "\" base=\"" + base.getID() + "\"");
            writer.tag("/Return");
        }
    }

    private static final class PathChoice {
        final int x;
        final int y;

        PathChoice(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}
